INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<p>Риҳан, барги бунӣ аз Ҳиндустон ва Ҷанубу Шарқи Осиё, ба сабаби хосиятҳои дорумонӣ, ҳиссиётӣ ва саноати бешумори худ, ҷои махсусро дар бозорҳои ҷаҳонӣ ва дохилӣ пайдо кардааст. Муваффақият дар деҳқонии тиҷоратии риҳан танҳо ба интихоби бӯғони сифатнок вобаста нест; идоракунии дақиқи манбаъҳои об ва гуно, бахусус тавассути технологияҳои навини обёрӣ, нақши ҳаётӣ дар муайян кардани <strong>ҳаҷми ҳосили риҳан дар ҳектар бо нӯбари типӣ дорад</strong> маҳсуб. Дар даҳсолаи охир, роҳбарии деҳқонҳо аз обёрии сатҳӣ ба сӯи обёрӣи тамчилӣ ва нӯбари типӣ тағйир ёфтааст, зеро ин роҳҳо на танҳо дар истифодаи об ҳарзагӣ мекунанд, балки бо офтадани намии мунтазам дар сатҳи реша, рушди якхела ва зиёд шудани самараро ба бор меоранд.</p><h2>Таъсири системаи обёрӣи нӯбари типӣ ба ҳосили риҳан</h2><p>Яке аз масъалаҳои асосӣ дар кишти риҳан, ҳассосии ин парваришӣ ба камобӣ ва инчунин парҳиз аз хунук шудани решаҳо аст. Системаҳои нӯбари типӣ, ки шакли яклухти лӯлаҳои пластикӣ бо шлангҳо ва нозлҳоеро, ки обро ба шакли нӯбар партоб мекунанд, ташкил медиҳанд, ин мушкилро ҳал менамоянд. Дар муқоиса бо обёрии сатҳӣ, нӯбари типӣ наморо бевосита дар минтақаи решаҳо фароҳам меорад. Ин боиси он мегардад, ки парваришӣ энергияи камтарро барои ҷидоли об сарф кунад ва диққати бештарро ба рушди вегетативӣ (барг ва ҷунбӯр) ва истеҳсоли моддаи хушк гардонад.</p><h3>Самаранокии об ва зиёд шудани сатҳи решаҳои фаъол</h3><p>Бо истифода аз обёрӣи нӯбари типӣ, сатҳи тамоси об бо хок беҳтар карда мешавад. Ин ба маънои зиёд шудани ҳаҷми хоки намноккардашуда дар маҳдудияти решаҳои ришаги дарахт аст. Таҳқиқот нишон медиҳанд, ки парвишиҳоеро, ки тавассути обёрӣи дақиқ пош карда шудаанд, то 30 то 50 фоиз зиёдтар аз муқобили онҳоеро, ки бо обёрӣи сатҳӣ обдоранд, мебароранд. Барои риҳан, ки ҳаҷми ҳосили он бевосита ба шумор ва андозаи баргҳои саломат вобаста аст, ин афзоиш дар самаранокии иқтисодӣ муҳим аст. Бинобар ин, сармоягузорӣ дар ин технология, роҳе барои кафолат кардани <strong>ҳаҷми ҳосили риҳан дар ҳектар бо нӯбари типӣ</strong> Баландтар, агар дигар шароитҳои кишоварӣ риоя шаванд.</p><p>Илова ба таҳсилоти об, системаи дрип имконияти гузаронидани фертиватсияро медиҳад. Дар ин усул, ҳаруҷҳонҳои ҳалшаванда бевосита бо оби обпоёӣ ба решаҳо ҷори карда мешаванд. Ин на танҳо самаранокии ҷазби ҳаруҷҳонро зиёд мекунад, балки шустани ҳаруҷҳон ба қабатҳои чуқури хокро пешгирӣ мекунад. Барои маълумоти бештар дар бораи таври дурусти интихоб ва насб кардани лӯлаҳо, метавонед ба мақола <a href="https://navar-abyari.ir/%D9%86%D8%AD%D9%88%D9%87-%D8%A7%D9%81%D8%B2%D8%A7%DB%8C%D8%B4-%DA%A9%D8%A7%D8%B1%D8%A7%DB%8C%DB%8C-%D9%88-%D8%A8%D9%87%D8%B1%D9%87%D9%88%D8%B1%DB%8C-%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C/">Равиши зиёд кардани самаранокии ва самаранокии системаи дрип</a> нигаред.</p><[IMAGE_1]><h2>Протоколи кишоварӣ ва парвариши рехана барои беҳтар кардани ҳосил</h2><p>Барои расидан ба сатҳи баландтарини ҳосили рехана, бояд аз марҳилаи кишодигӣ то ҳосилгирӣ, протоколҳои муайян риоя шавад. Рехана растание аст, ки ба рӯшноии пурра, хок зард ва зардпур ва ҳарорати мулоим ниёз дорад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/میزان-برداشت-ریحان-در-هکتار-با-نوار-تیپ-تصویر-شاخص.webp" alt="میزان برداشت ریحان در هکتار با نوار تیپ - تصویر 1"/><figcaption>crop yield per hectare drip irrigation рехана</figcaption></figure><h3>Кишодигӣ ва идоракунии зардпурӣ</h3><p>Беҳтарин вақти нақли буттаҳои бунядии ретан дар минтақаҳои мулоим баҳор аст. Данаҳои ретан хурданд ва ба нақли сатҳӣ ниёз доранд. Баъд аз нақл, хок бояд бо эҳтиёт бокандав шуда ва оборӣ оғоз шавад. нуқтаи муҳим ин аст, ки аз гарк хӯрди решаҳо пешгирӣ карда шавад, зеро решаҳои ретан ба оксиген ҳассос мебошанд. Дар системаи нақбандӣ (дропнет), бо танзиби дурусти фишор ва раъҷоб кардани об, метавон аз об фароварӣ пешгирӣ кард. Нақли сабзиҳо монанди лӯбиё ё рӯёнҳои пӯшанда метавонад ба нигоҳ доштани намии хок кӯмак расонад. Барои фаҳмиши беҳтари таъсири нақли сабзӣ бар хок, боварии мавзӯъро таҳқиқ кунед. <a href="https://navar-abyari.ir/miqdori-tuxmi-javori-donador-dar-yak-gektar/">Миқдори тухми ҷирҷироси донадор дар як гектар</a> метавонад боварии хубро дар бораи идоракунии кроппҳои ҳамроҳ ва таъсири онҳо ба муҳити нақл таъмин кунад.</p><h3>Идоракунии оборӣ ва ғизоиднокунӣ</h3><p>Оборӣ ба ретан бояд мунтазам ва доимӣ бошад. Дар системаҳои нақбандӣ (дропнет), ин кор хеле осон аст. Ретан ба калий ва азот ҷавоби хуб медиҳад, аммо истифодаи зиёди маҳлули метавонад лаззат ва афруги онро паст намояд. Маслиҳат дода мешавад, ки аз маҳлулҳои органикӣ монанди компост ҳамчун асос ва маҳлулҳои маҳлулшудаи моеъ ҳамчун илова истифода шавад. Дар мавсими афрӯиш, ниёзи ретан ба об баланд мешавад, вале набояд имкон дода шавад, ки хок хушк шавад ва баъдан гарк хӯрад; намии якхела калиди муваффақият аст.</p><[IMAGE_2]><h2>Интишоъ ва сифати маҳсул: омили муайянкунандаи ҳосилот</h2><p>Интишоъи ретан бо шакли тоза, хушк, роғноӣ ё эфирӣ, зарурати идоракунии сифати маҳсулро дорост. Ретани тоза бояд фавран пас аз харидан, дар ҳарорати хунук нигоҳ дошта шавад. Баргҳои ретан пас аз як ҳафта лаззат ва хусусияти доруии худро аз даст медиҳанд. Бинобар ин, системаи муқаррарии харидан ва бастабандии саломатбахш хеле муҳим аст.</p><h3>Харидан ва пас аз харидан</h3><p>Кушодани барги кӯлаҳои эспарто (риҳон) барои истеъмоли тоза бояд дар он вақт иҷро шавад, ки дарахтоҳашон қавӣ бошанд ва як қадар баргҳои ҷавон кушода бошанд. Беҳтарин вақти кушодан осебҳои субҳ аст, ки буяш метаноз. Агар мақсади содирот барги эспарто (риҳон) хушк бошад, бояд баргҳо аз дарахт ҷудо карда шуда дар соя ва ҳавои хушк хушканд. Як нуқтаи амалӣ, ки метавонад ба зиёд кардани сифат ва самаранокии системаи умумӣ кӯмак кунад, омӯзиш аст, <a href="https://navar-abyari.ir/tuxmi-bodjngon-dar-gapter-maslahathoi-shanon-obori/">Мулоҳизаҳои эҳтимолии нисбати анор дар кӯчаҳои гунбазӣ (ғизоӣ)</a> аст; гарчанде дар бораи як наботати дигар бошад, вале принсипҳои нигоҳ доштани ҳаво дар фазои маҳдуд барои нигоҳ доштани буя ба таври мумоил рӯй ба рӯй ба рӯй ба рӯй нишаст</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/میزان-برداشت-ریحان-در-هکتار-با-نوار-تیپ-کاربرد-عملی.webp" alt="میزان برداشت ریحان در هکتار با نوار تیپ - تصویر 2"/><figcaption>crop yield per hectare drip irrigation РИҲОН</figcaption></figure><h2>Нуқтаҳои амалӣ барои муваффақият дар кундубории эспарто (риҳон) бо усули нӯрипо</h2><p>Барои деҳқононе, ки нияти кундубории тиҷоратии эспарто (риҳон) доранд, риояи як қанча нуқтаҳои амалии зерин метавонад калидӣ бошад барои зиёд кардани <strong>ҳаҷми ҳосили эспарто (риҳон) дар ҳектар бо усули нӯрипо</strong> бошад:</p><ul><li><strong>Муайян кардани фосилаи кундӣ:</strong> Барои расидан ба рӯшноии кофӣ ба ҳамаи дарахтон, фосилаи байни дарахтон 10 то 15 сантиметр ва фосилаи байни қаторҳо 40 то 60 сантиметр тавсия карда мешавад.</li><li><strong>Кунд кардани чанд фаслӣ:</strong> Бо кунд кардани пайдарпай бо фосилаҳои 2 то 4 ҳафта, метавон аз фосилаи доимии ҷамъоварӣ дар тӯли фасли кундӣ истифода бурд.</li><li><strong>Идоракунии зараровар ва бемориҳо:</strong> Райҳан ҳассос ба занбӯруҳои хокӣ аст. Барои кам кардани бемориҳои занбӯруӣ, метавон аз кундҳои бадлишуда бо ҳашамҳои ғайри ғизоӣ, ба монанди шумораи бардошт чормақзи сабз дар гектар + нуқтаҳои кунд ва дошт истифода бурд, ки аз ҷиҳати экологӣ бо райҳан вайронӣ надоранд ва ба шикастани ҳалқаи зарароварҳо кӯмак мекунанд.</li><li><strong>Ҷоридани соҳии лӯлаҳо:</strong> Ноззлҳои наварро ҳар моҳ санҷед. Қатъи сӯрохҳо бо кӯфт ё зарраҳо метавонад боиси обёрии ноафзоянд гарданд. Ҳаргиз аз пахтаи тефлон боштан барои пӯшидани ноззлҳо истифода набаред; аз бастанҳои гардон истифода баред.</li><li><strong>Истифодаи пахт:</strong> Дар минтаҳои гарм ва хушк, пӯшидани хок бо пахт то ба 20 фоиз ниёз ба обро коҳиш дода метавонад ва ҳарорати хокро дар тӯли рӯз мувозинат бардорад.</li></ul><[IMAGE_3]><h2>Саволҳои маъмулӣ (FAQ)</h2><h3>1. Миқдори миёнаи барои бадам кардани раиган чӣ қадар аст?</h3><p>Дар миёнаи фасли афзоиш, ниёз ба об барои раиган аз 4 то 6 либр дар рӯз бар метри мурабат метавонад расад, вобаста ба иқлим. Дар системаи ороғии қатрагӣ (капель), ин миқдор бо 3 то 5 маротиба ороғии кӯтоҳмуддат дар як рӯз тақсим карда мешавад, то аз тарри зиёдатӣ пешгирӣ шавад.</p><h3>2. Оё имкони истифодаи ороғии қатрагӣ барои раиган дар фазои мӯҳкам вуҷуд дорад?</h3><p>Бале, ороғии қатрагӣ барои гулкорҳои калон ё боғчаҳои дохилӣ хеле мувофиқ аст. Дар фазои мӯҳкам, дақиқият дар танзими сарф (дебит) муҳимтар аст, зеро фазои баромадан ва ҳавогирии кам дорад.</p><h3>3. Чӣ тавр метавонам аз сирояткунӣи зангор (қалам) дар хок бо истифода аз ороғии қатрагӣ пешгирӣ кунам?</h3><p>Бо танзими дақиқи вақт ва миқдори оборӣ, шумо метавонед аз таркиши зиёдатӣ ва зарф, ки омил асосии рушди занбӯруғ аст, пешгирӣ кунед. Бинобар ин, истифодаи таъсири мувофиқ, ҳаракат намудани қоидаҳо ва интихоби системаи сифатнок метавонад ба кам шудани кортумӣ оварда расонад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/میزان-برداشت-ریحان-در-هکتار-با-نوار-تیپ-جزئیات-فنی.webp" alt="میزان برداشت ریحان در هکتار با نوار تیپ - تصویر 3"/><figcaption>Crop yield per hectare drip irrigation Ройхан</figcaption></figure><h3>4. Оё ройхан бо дигар наботот хуб мерӯяд?</h3><p>Ройхон метавонад бо саривалӣ, сабзавотҳои баргдор ва болворот хуб бошад. Ин намуди наботот метавонанд дар пешгирии зарароварон ва истифодаи самараноки нур ва тағзимот кӯмак расонанд.</p><h3>5. Чӣ гуна решаҳои ройхонро дар кашонҳои хурдро бо нобҳои нақшинӣ идора кунем?</h3><p>Дар кашонҳои хурд аз нақшиниҳое истифода баред, ки миқдори обдиҳӣ нисбатан кам доранд ва масоҳаташон зиёдтар аст. Решаҳо бояд байни масоҳати нақшинҳо обро қабул кард. Назорати решаҳо дар ҳар моҳ барои таҳримоти саломатии онҳо муносибат мекунад.</p><h2>Хулоса</h2><p>Аз 1000 метри мураббаъ кам, ки дар кушодани саҳоби ройхон корӣ метавонад ба як тиҷорати хуб табдил ёбад. Гарчанде ки интихоби бӯғи сифатнок ва парвариши наботот муҳим аст, системаи обори нақшинӣ калиди асосии зиёд кардан ба самаранокӣ ва коҳиши сарфишавии тадбирӣ мебошад. Ин система бо тартиб додани решаҳо, аз истифодаи зиёдтар об дар корӣ пешгирӣ мекунад, имконияти тағзимакии дақиқро фароҳам меорад ва дар натиҷа, ба чорводорона имкон медиҳад, ки <strong>Ҳосилнокии пистоидар ҳектар бо нарв типӣ</strong> ро дар сатҳи баландтари меъёрҳои анъанавӣ нигоҳ дорад. Бо риояи маслиҳатҳои амалии ин мақола, аз ҳолтокиш то ҳосилдоштан, шумо метавонед маҳсулоти тоза, солим ва сифати баланд истеҳсол кунед, ки дар бозорҳои маҳаллӣ ва экспортӣ талаботи хеле баланд дорад.</p>\n<p><strong>Мавзӯҳои алоқаманд:</strong> <a href="https://navar-abyari.ir/parsley-yield-per-hectare-increase-methods/">parsley yield per hectare increase methods</a></p>','Маводи ҳасили реҳнано дар як гектар бо системаи ноқили ғалвора: Раҳнамои пурраи кӯдаку ғаллорӣ','Рیحан яке аз растаниҳои доруии арзишманд бо хосиятҳои ҷудогона аст. Дар ин мақола ба таҳлил таъсири системаҳои обори пешрафта, бешубора нвар чип, ба зиёдшавии ҳосили рیحан дар ҳектар муроҷиат мекунем ва нуқтаҳои асосии нишонадӣ ва парвариши онро муаррифӣ менамоям.','publish','closed','closed','hosili-rehnano-dar-1-hektar-sistemi-irrigatsiya',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
