INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима: Аҳамияти муайян кардани дақиқи зичии партовии шпинат</h2>\n<p>Шпинат як растании ду сол аст, ки дар мавсими сарди сол барои истеҳсоли баргҳои хӯроквор партоб карда мешавад. Ба фарқ аз бисёр сабзиёте, ки тавассути тақсимоти реша истеҳсол мешаванд, шпинат растание решаи спорогенӣ аст, ки суръати руиши худро баланд дорад. Бинобар ин, яке аз мушкилоти асосии деҳқонон дониши дақиқи ин аст, ки <strong>Миқдори бехи шпинат дар ҳектар</strong> чӣ қадар бояд бошад, то ҳам зичии муносибе барои фарогирии замин дошта бошем ва ҳам аз рақобати шадиди растаниҳо бо якдигар дар ҷазби об ва моддаҳои ғизоӣ пешгирӣ кунем.</p>\n<p>Дар системаҳои навори нави чак-чакӣ, идоракунии зичии партоб мустақиман ба сармофи об ва энергия таъсир мерасонад. Партоби ғайриоддӣ метавонад боиси ноустуворшавии нури рӯшноӣ ба баргҳои поёнӣ ва зиёд шудани бемориҳои қулеҳзорӣ гардад, дар ҳоле ки партоби ғайриоддӣ истеҳсоли ниҳоии маҳсулотро ба ҳар ҳектар коҳиш медиҳад. Мақсади ин дастрақом муаррифӣ кардани формулаи иҷроне барои муайян кардани дозаи бех аз рӯи шартҳои муҳитӣ мебошад.</p>\n\n\n\n<h2>Омилҳои таъсиркунанда ба муайян кардани миқдори бехи шпинат</h2>\n<p>Муайян кардани дозаи бех якҳамкор нест ва бояд асосан ба тағйирёбандаҳои зерин ҳисоб карда шавад. Аввалин омили асосӣ, <strong>Нави бех</strong> Баъзан доноти гуногун (масалан, баъзе намудҳои анъанавӣ) барои таъмини ҷунбиши якхел ба дони бештар ниёз доранд. Аммо доноти гибридӣ ва беҳбуда хосияти баланди ҷунбиданро доранд ва бо дани камтар шикунида мешаванд.</p>\n<ul>\n<li><strong>Шароити иқлимӣ:</strong> Дар минтақаҳои хушк ва гарм, шикунии дар замон муносиб (тобистон ё охири зимистон) муҳим аст. Шикуни зодру аз ҳавои гарм оғоз мешавад ва сифати маҳсулро мекушояд.</li>\n<li><strong>Усули шикунии:</strong> Шикунии зич бо машинаи шикунии паҳшкунанда (Scatter Seeding) одатан ба дони бештар ниёз дорад, то баъдтар тавассути паҳши ё коркард зичии шикуни танҷуб шавад. Шикунии бо рақибҳо бо фосилаи дақиқ ба дони камтар ниёз дорад.</li>\n<li><strong>Навъи хок:</strong> Дар хокҳои сабук ва шабмонӣ ҷабиши намнокӣ тезтар аст, бинобар ин шояд ба идоракунии дақиқтари обёрӣ ва, натиҷавӣ, танҷуби оптималии фосилаи шикуни ниёз дошта бошем.</li>\n</ul>\n\n<h3>Унсурҳои ҳисобии дони доно</h3>\n<p>Барои ҳисобкунии дақиқ, бояд се параметри асосиро ба назар гиред: фоизи навмашӣ (VI), вазни ҳазор дана (WTK) ва зичии ниҳоии ҳадафӣ. Ғарчанде ки чинӣ гиҳиест, ки одатан бо тартиби сатҳӣ ва зич коркӣ мешавад, аммо дар системаҳои обёрӣ-поёнӣ ва наварҳо, ки одатан барои маҳсулоти андозаи калонтар, ба монанди зиракӣ ё думарӣ истифода мешаванд, баҳс <strong>Микдори бисмчии чинӣ дар гектар</strong> бо мақсади мутобиқсозӣ барои пешгирии талофоти об дар фазои холӣ байни сатҳҳо. Ғарчанде ки чинӣ одатан дар фазои кушода коркард мешавад, аммо истифодаи обёрӣ-поёнӣ дар ҳудуди Маджи ё заминҳои калон барои кам кардани сарфи об тавсия дода мешавад. Барои фаҳмиши беҳтари фарқият байни системаҳои обёрӣ ва таъсири он ба идоракунии коркӣ, шумо метавонед мақолаи «Обёрӣ-мустақими замини кишоварзӣ: муфаввод ва ноуставҳо»-ро омӯзед, то назари васеътар дошта бошед.</p>\n\n<h2>Раванди коркӣ ва зичии тавсияшуда</h2>\n<p>Дар коркарди оддии чинӣ, масоҳати байни сатҳҳо одатан аз 20 то 30 сантиметр ва масоҳати дохили сатҳҳо аз 10 то 15 сантиметр аст. Бо ин ҳисоб, зичии рӯяниҳо аз 100,000 то 150,000 дона дар гектар тағйир меёбад. <strong>Микдори бисмчии чинӣ дар гектар</strong> Вобаста ба вазни думарӣ ва вобаста ба навъи интихобшуда, одатан аз 10 то 15 килограмм дар гектар тағйир меёбад. Аммо ин рақам қоидаи собит нест ва бояд бо фоизи навмашӣ танзим карда шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-اسفناج-در-هکتار-راهنمای-جامع-تصویر-شاخص.webp" alt="مقدار بذر اسفناج در هکتار: راهنمای جامع - تصویر 1"/><figcaption>Микдори бисмчӣ дар гектар барои чинӣ</figcaption></figure>\n\n<h3>Ҷадвали муҳаррири ҳисобкунии миқдори бубурҳиш</h3>\n<p>Ҷадвали зерин рамзери пуррасад аст, ки барои ҳисобкунии миқдори ниҳоии бубурҳиш асосан ба дарсади рушд мебошад. Ин усул ба деҳқон кӯмак мекунад, ки партовҳои табиӣ-и бубурҳишро (бо сабаби ғунидонии нобод, сӯхт ё шароитҳои хоб) ислоҳ кунад.</p>\n<table style="width:100%; border-collapse: collapse; text-align: left;">\n    <thead>\n        <tr style="background-color: #f2f2f2;">\n            <th style="border: 1px solid #ddd; padding: 8px;">Дарсади рушди бубурҳиш</th>\n            <th style="border: 1px solid #ddd; padding: 8px;">Муносибати ислоҳ-кунии миқдор</th>\n            <th style="border: 1px solid #ddd; padding: 8px;">Миқдори тавсияшудаи бубурҳиш (килограмма/гектар)</th>\n        </tr>\n    </thead>\n    <tbody>\n        <tr>\n            <td style="border: 1px solid #ddd; padding: 8px;">Беш аз 90%</td>\n            <td style="border: 1px solid #ddd; padding: 8px;">1.0 (стандарт)</td>\n            <td style="border: 1px solid #ddd; padding: 8px;">Аз 10 то 12</td>\n        </tr>\n        <tr>\n            <td style="border: 1px solid #ddd; padding: 8px;">75% то 90%</td>\n            <td style="border: 1px solid #ddd; padding: 8px;">1.2 (муқаррарӣ)</td>\n            <td style="border: 1px solid #ddd; padding: 8px;">12 то 15</td>\n        </tr>\n        <tr>\n            <td style="border: 1px solid #ddd; padding: 8px;">зери 75%</td>\n            <td style="border: 1px solid #ddd; padding: 8px;">1.4 (таъмиравӣ)</td>\n            <td style="border: 1px solid #ddd; padding: 8px;">15 то 18</td>\n        </tr>\n    </tbody>\n</table>\n\n<p>Диққат нависед, ки ин рақамҳо тақрибанӣ мебошанд ва беҳтар аст, ки пеш аз хариди ниҳоӣ, фоизи номиқоди бубази хоҳиши худро дар лаборатория санҷед. Истифодаи бубази сифати баланд дар тӯли муҳлати дароз, гароникиро коҳиш медиҳад. Агар дар ҷустуҷӯи маҳсулоти садори дигар бошед, ҳисобҳои алоқаманд <a href="https://navar-abyari.ir/melon-seed-quantity-per-hectare-planting-density-table/" target="_blank" rel="noopener">меъёри бубази хурбӯза дар гектар ва ҷадвали zichatkii калонкунӣ</a> инчунин фоидаовар аст, зеро намунаи идоравии монанд бо маҳсулоти сабзи дучин дорад.</p>\n\n\n\n<h2>Обиёрии қатрагӣ ва тарқати шириндаракӣ дар парвариши шпинат</h2>\n<p>Яке аз хатогиҳои умумии бешумор дар парвариши сабзӣ истифодаи обиёрии гармнокунда барои шпинат аст. Шпинат ба рӯят якхела ниёз дорад, вале барои пардохти решаҳо ҳассос аст. Истифодаи системаи обиёрии қатрагӣ ё тарқати шириндаракӣ (Tape) имконияти назорати дақиқи миқдори об ва иғизо фароҳам меорад. Ин системаҳо имкон медиҳанд, ки решаҳои шпинат дар давоми давраи афзоиш дар ҳолатҳои муносиб нигоҳ дошта шаванд.</p>\n\n<h3>Таъсири системаи обиёрӣ ба интихоби зичии ғӯтиш</h3>\n<p>Вақте ки шумо тарқати шириндаракӣ (Tape)-ро истифода мебаред, масофаи лӯлаҳои шириндаракӣ бо хатҳои ғӯтиш бояд комилан мувофиқ бошанд. Агар шумо муқаррар кунед, ки зичии ғӯтишро барои расидан ба самаранокии баландтар зиёд кунед, бояд таъмин кунед, ки қуввати хориҷи ноззиҳо (Emitters) системаи обиёрии шумо қобилияти таъмин кардани он зичии баландро дорад. Дигар, ниҳоён бо норасобии об рӯ ба рӯ хоҳанд шуд. Як раҳнамоии пурра дар бораи <a href="https://navar-abyari.ir/irrigation-tape-squash-guide/" target="_blank" rel="noopener">нависонидан ва танзими тарқати шириндаракӣ барои кӯдаконаву сабзӣ</a> дар тарҳрезии системаи шумо кофӣ аст. Гарчи раҳнамоии кӯдакона ба маҳсулоти мушаххис кардашуда иқтидор аст, принсипҳои техникии тарқати шириндаракӣ барои сабзи дучин ба мисли шпинат низ татбиқ карда мешавад.</p>\n\n<h3>Нуктаҳои амалӣ дар ғӯтиш ва обиёрӣ</h3>\n<p>Барои камоли парвариши спинак бо обӣи нав, ин нуқтаҳои асосиро риоя кунед:</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-اسفناج-در-هکتار-راهنمای-جامع-کاربرد-عملی.webp" alt="مقدار بذر اسفناج در هکتار: راهنمای جامع - تصویر 2"/><figcaption>меъёри бехкашӣ бар ҳектари парвариши спинак</figcaption></figure>\n<ol>\n<li><strong>дастрасӣ ба бехкашӣ:</strong> Вақте ки аз системаи тамчабарӣ истифода мебаред, таъмин кунед, ки бехҳои спинак дақиқ дар сари холаҳо ё байни холаҳо ҷойгир шудаанд, то ки ба решаҳои минтақаҳои марказӣ дастрасӣ дошта бошанд.</li>\n<li><strong>мадорсозии аввалия:</strong> Агар аз усули паҳкунӣ (Scatter) истифода баред, пас аз он ки буттаҳо ба баландии 15 сантиметр расанд, бояд тавассути мавҷуд будани дастӣ ё механикӣ масофаи байни буттаҳоро ба масофаи мақсаднок расонед. Ин кор ҳаромест, аммо самаранокиро таъмин мекунад.</li>\n<li><strong>идоракунии бех:</strong> Дар ҳолати истифодаи бехҳои пӯшонидашуда (Coated Seeds), миқдори бехкаширо кам кунед, зеро бехи пӯшонидашуда сабаби вазни баландӣ паҳншавии дақиқтарро нишон медиҳад.</li>\n</ol>\n\n<p>Муқоисакунии ҳосили сабзи бо дигар сабзавот аз ҷиҳати самаранокӣ метавонад дар барномарезии иқтисодии шумо муфид бошад. Барои давоми иттилоот оид ба миқдори тоҷи хияр дар як гектар ва нуқтаҳои калидии ниҳолкорӣ, шумо метавонед аз ҳамон принсипҳои техникӣ дар системаҳои обёрӣ истифода баред, бо фарқе, ки масоҳати ниҳолкории хияр пурра аст ва барои афзоиши пулакҳо ҷои зиёдатар лозим аст. Сабз ҳамчун маҳсули тезбарориш, роҳи ҳамкории мутаносибро дар идоракунии вақт талаб мекунад.</p>\n\n\n\n<h2>Саволҳои оддӣ дар бораи парвариши сабз</h2>\n<p>Дар зер ба баъзе саволҳои омориди кишоварон оид ба <strong>миқдори тоҷи сабз дар як гектар</strong> ва ҷавоб ба нуқтаҳои иловагӣ дода мешавад:</p>\n\n<h3>1. беҳтарин фаввора барои ниҳолкории сабз дар минтақаҳои мулоими Эрон каҷ аст?</h3>\n<p>Ниҳолкории сабз арзёбаман дар паҳлӯй (асфанд то абан) иҷро мегардад, то ки ғизо ҳаво барои парвариш ишрат кунад ва бобо хатшавӣ дар баҳор суръат пайдо кунад. Ниҳолкории ғадаҳи баҳор хатари ғилаккуниро баланд мебардорад.</p>\n\n<h3>2. оё тоҷи сабз барои пеш омодагиранд лозим аст?</h3>\n<p>Боби калланда қатил қабиға эҳияд, ки инчунин бодишро дероз мекунандашонад. Хоби боби дар оби ҳарорати муҳит барои 12 то 24 соат бодишро беҳтар мекунад. Инчунин, баъзан боби бояд бо санги асбоб (бушадгиҳои нарм) ё усулҳои кимиёвӣ (саидгиҳо) кор шаванд, то ки қаби шикаста шавад, гарчанде ки ин кор камтар маъмул шудааст.</p>\n\n<h3>3. Нақши чуқурии кариш дар <strong>Микдори боби калланда дар як гектар</strong> чи аст?</h3>\n<p>Чуқурии кариши калланда бояд кам бошад, одатан 1 то 2 сантиметр. Агар чуқурӣ аз 2 сантиметр зиёд бошад, энергияи боби барои шикастани хок ва расидан ба сатҳ кофӣ нест ва шумо бодиши камро мебинед. Ин ба он оварда мерасонад, ки шумо маҷбур шавед миқдори боби худро зиёд кунед, ки харҷнок аст ва инчунин зичии нохушро эҳод мекунад. Коркунандаи дақиқ чуқурии кариш бо мошин фоидабарро беҳтар мекунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-اسفناج-در-هکتار-راهنمای-جامع-جزئیات-فنی.webp" alt="مقدار بذر اسفناج در هکتار: راهنمای جامع - تصویر 3"/><figcaption>миқдори боби калланда дар як гектар</figcaption></figure>\n\n<h3>4. Оё аз системаи обёркунии нӯрип барои калланда истифода мебарем?</h3>\n<p>Бале, истифодаи нӯрип бо андозаи лӯлаи мувофиқ (одатан лӯлаҳои бо андозаи хурдтар барои кам кардани харҷҳо) тавсия карда мешавад. Фосилаи байни лӯлаҳо бояд бо фосилаи сатҳҳои кариши калланда мувофиқ бошад. Барои раҳоӣ дар бораи танзими техникӣи лӯлаҳо, шумо метавонед рамзҳои фосилаи нӯрип ва кариши гулакҳоро ҳамчун рамзи техникӣ дар бораи фосилаҳои мутавазифона омӯзед; принсипҳои ҳисобкунии фишор ва ҷараён бошакш барои маҳсулоти сабзавотҳо таҳлил карда мешавад.</p>\n\n<h2>Хулоса: Истифодаи оптимизатсияи ҳарҷ ва самаранокият</h2>\n<p>Муайяни дақиқ <strong>Миқдори бехи спанач дар 1 гектар</strong> Ин раванди сода нест, балки як мувофиқати дарки бех, муҳитшиносӣ ва муҳандисии обкунӣ мебошад. Бо риёяти нуқтаҳои зерин, шумо метавонед беҳтарин самаранокияти иқтисодиро ба даст оред:</p>\n<ul>\n<li>Аз бехҳои дорои <strong>ҳиссаи баланди рушд</strong> истифода баред, то ниёз ба дози иловагии таъмин кардани камбудӣ набошад.</li>\n<li>Фосилаи кӯмакунро бо раъй <strong>Қобилияти системаи ошкории</strong> (қатраеӣ ё пич) мувофиқ созед.</li>\n<li>Баъд аз бунбонӣ, асос меъёри ниҳоии <strong>Зичнокунӣ</strong> ро анҷом диҳед.</li>\n</ul>\n<p>Местоифидакунии самаранок аз системаҳои ошкорӣ на танҳо сарф-номро кам менамояд, балки бо сабаби якхел будани рушд, ҷойи ҳосилро якбора ва зерибати хосаи меҳваронаро таъмин мекунад. Дар охир, назорати давомдори тарри хок ва ҳолати гиёҳон дар давраҳои гуногуни рушд, калиди муваффақият дар ҳосилкории спинокӣ мебошад. Барои васеъсозии дониши фаннашӯнакони худ, таҳқиқ манбаъҳо вобаста ба <a href="https://navar-abyari.ir/seed-amount-spinach-hectare-optimal-methods/" target="_blank" rel="noopener">Кубуррасонии усули бунбонии сабзавот</a> ва санҷиши нақшаҳои ҳосилкории муташаккул пешниҳод менамоянд, то шаавонае барои ҳамагӣи заминии худ истифода бароред.</p>\n<p><strong>Мавзӯи дастигирӣ:</strong> <a href="https://navar-abyari.ir/chickpea-seed-per-hectar-iraq/">chickpea seed per hectar iraq</a></p>','Миқдори бехи сабз: Раҳнамои умумӣ барои кишт ва обёрӣ','Корзони шуборак яке аз сабзавотҳои фоидавартарин дар мавсими сохт ва ним-сохт аст. Муваффақият дар ин ҷорӣ бевосита ба интихоби навъи бовиру муайян кардани дақиқи «мӯҳлати бовиру дар гап сабзавот» вобаста аст. Дар ин мақола, бо фарз кардани корзони дар заҳрҳои системаи ирригатсионии наврҳои навоварӣ ва нуронишҳо, масъалаи фиғурро, фосилаи фазоӣ ва идоракунии захиравҳоро таҳлил карда, аз талафоти сармоя ва коҳиши самаранӯмӣ пешгирӣ мекунем.','publish','closed','closed','miqdori-behi-sabz-baroyi-kishtu-obori',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
